    import { mapState, mapMutations } from 'vuex'
    export default {
        name: 'z_wechat_attention',
        cname: '关注公众号',
        configName: 'c_wechat_attention',
        icon: '#iconzujian-gongzhonghao',
        type: 2, // 0 基础组件 1 营销组件 2工具组件
        defaultName: 'follow', // 外面匹配名称
        props: {
            index: {
                type: null,
                default: -1
            },
            num: {
                type: null
            }
        },
        computed: {
            ...mapState('admin/mobildConfig', ['defaultArray'])
        },
        watch: {
            pageData: {
                handler (nVal, oVal) {

                },
                deep: true
            },
            num: {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[nVal]
                    this.setConfig(data)
                },
                deep: true
            },
            'defaultArray': {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                    this.setConfig(data);
                },
                deep: true
            }
        },
        data () {
            return {
                // 默认初始化数据禁止修改
                defaultConfig: {
					cname: '关注公众号',
                    name: 'follow',
                    timestamp: this.num,
					isHide:false,
                    setUp: {
                        tabVal: 0
                    },
					titleLeft:'标题设置',
					positionTitle:'位置设置',
					pictrueTitle:'图片设置',
					codeTitle:'关注二维码',
					titleRight:'关注按钮',
					titleCurrency:'通用样式',
					positionConfig:{
						title:'展示位置',
						tabVal: 0,
						tabList: [
						  {
						    name: '顶部'
						  },
						  {
						    name: '底部'
						  }
						]
					},
                    titleConfig: {
                        title: '标题名称',
                        value: '标题',
                        place: '请输入标题',
                        max: 10
                    },
                    imgConfig: {
                        info: '建议：图片尺寸92px * 92px',
                        url: '',
						type:'code',
						name:'上传图片'
                    },
                    codeConfig: {
                        url: '',
						type:'code',
						name:'上传二维码'
                    },
                    themeColor: {
                        title: '按钮颜色',
                        default: [
                            {
                                item: '#E93323'
                            }
                        ],
                        color: [
                            {
                                item: '#E93323'
                            }
                        ]
                    },
                    bgColor: {
                        title: '背景颜色',
                        default: [
                            {
                                item: '#fff'
                            },
							{
							    item: '#fff'
							}
                        ],
                        color: [
                            {
                                item: '#fff'
                            },
							{
							    item: '#fff'
							}
                        ]
                    },
					prConfig: {
						title: '左右边距',
						val: 0,
						min: 0
					},
                    mbConfig: {
                        title: '页面上间距',
                        val: 0,
                        min: 0
                    },
					fillet:{
						title:'背景圆角',
						type: 0,
						list: [
						  {
						    val: "全部",
						    icon: "iconcaozuo-zhengti",
						  },
						  {
						    val: "单个",
						    icon: "iconcaozuo-bianjiao",
						  }
						],
						valName:'圆角值',
						val: 0,
						min: 0,
						valList:[
							{val:0},
							{val:0},
							{val:0},
							{val:0}
						]
					}
                },
                cSlider: '',
                bgColor: '',
                confObj: {},
                pageData: {},
                edge: '',
                udEdge: '',
                themeColor: '',
                mTOP: 0,
                imgUrl: '',
                txt:'',
				mlConfig:0,
				fillet:0,
				filletVal:0,
				valList:[]
            }
        },
        mounted () {
            this.$nextTick(() => {
                this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                this.setConfig(this.pageData)
            })
        },
        methods: {
            setConfig (data) {
                if(!data) return
                if(data.mbConfig){
                    this.bgColor = data.bgColor.color
                    this.themeColor = data.themeColor.color[0].item
                    this.mTOP = data.mbConfig.val;
                    this.imgUrl = data.imgConfig.url
                    this.txt = data.titleConfig.value
					this.mlConfig = data.prConfig.val
					this.fillet = data.fillet.type;
					this.filletVal = data.fillet.val;
					this.valList = data.fillet.valList;
                }
            }
        }
    }
